<?php
use Sigesp\Core\View;
$page = $page ?? [];
$screenLabels = ['index' => null, 'novo' => 'Novo cadastro', 'perfil' => 'Detalhes', 'analise' => 'Análise', 'tipos' => 'Tipos de documento', 'registrar' => 'Registrar frequência', 'relatorio' => 'Relatório', 'calendario' => 'Calendário', 'movimentacoes' => 'Movimentações', 'visualizar' => 'Visualizar relatório'];
$screen = $page['screen'] ?? 'index'; $title = $screenLabels[$screen] ?? 'Painel';
?>
<?php View::component('page-header', ['eyebrow' => 'Módulo visual', 'heading' => $screen === 'index' ? $page['title'] : $page['title'] . ' · ' . $title, 'description' => $page['description'], 'actionLabel' => $page['action'], 'actionHref' => '#']); ?>
<?php if ($screen === 'index'): ?><section class="stats-grid"><?php foreach ($page['cards'] as [$icon, $label, $value, $detail]) View::component('stats-card', compact('icon','label','value','detail')); ?></section><?php ob_start(); ?><form class="filter-form"><label class="field">Buscar<input placeholder="Pesquisar registros" disabled></label><label class="field">Situação<select disabled><option>Todos</option></select></label><label class="field">Período<input type="month" disabled></label><div><button class="button" type="button" data-toast="Os filtros serão conectados ao serviço do módulo.">Aplicar filtros</button></div></form><?php $filterContent = ob_get_clean(); View::component('filter-bar', ['filters' => $filterContent]); ?><section class="surface"><div class="surface__header"><div><h2><?= View::e($page['section']) ?></h2><p>Esta tela está pronta para receber dados reais quando o módulo operacional for conectado.</p></div></div><?php View::component('empty-state', ['heading'=>'Nenhum registro disponível','message'=>'Não há dados demonstrativos misturados aos registros operacionais. As ações visuais permanecerão seguras até a integração do módulo.']); ?></section><?php else: ?><section class="surface"><div class="surface__header"><div><h2><?= View::e($title) ?></h2><p>Fluxo visual preparado sem alterar dados reais.</p></div></div><?php if ($screen === 'novo'): ?><form class="form"><div class="form-grid"><label class="field">Nome ou título<input disabled></label><label class="field">Situação<select disabled><option>Selecionar</option></select></label><label class="field">Observações<textarea disabled rows="3"></textarea></label></div><footer class="form-actions"><a href="<?= View::e(View::url('/' . $page['module'])) ?>" class="button button--secondary">Cancelar</a><button type="button" class="button" data-toast="O salvamento será habilitado junto à regra operacional.">Salvar</button></footer></form><?php else: ?><?php View::component('empty-state', ['heading'=>'Aguardando dados do módulo','message'=>'Os detalhes aparecerão aqui quando houver uma fonte de dados autorizada para esta funcionalidade.','actionLabel'=>'Voltar para '.$page['title'],'actionHref'=>'/'.$page['module']]); ?><?php endif; ?></section><?php endif; ?>
